package com.amdocs.telecom.bss.model;

import java.math.BigDecimal;
import java.time.LocalDate;

/** Immutable request models. Identifiers and registration timestamps are generated by the server. */
public final class Domain {
    private Domain() { }
    public enum Role { CUSTOMER, ADMIN }
    public enum UsageType { VOICE, SMS, DATA, ROAMING }
    public enum PaymentMode { UPI, CARD, NET_BANKING, BANK_TRANSFER }
    public enum Category { BILLING, NETWORK, SIM, PLAN, PAYMENT, OTHER }
    public enum Priority { LOW, MEDIUM, HIGH, CRITICAL }
    public record Registration(String username,String firstName,String lastName,LocalDate birthDate,
                               String email,String mobile,String address,String city,String country) { }
    public record Plan(String code,String name,String type,BigDecimal rental,BigDecimal dataGb,int voiceMinutes,
                       int sms,int validityDays,boolean roaming,boolean active,int minimumTenureDays,
                       boolean allowTypeChange,BigDecimal dataRate,BigDecimal voiceRate,
                       BigDecimal smsRate,BigDecimal roamingRate) { }
    /** Token is deliberately omitted from display/logging. */
    public record Session(String token,String username,Role role) {
        @Override public String toString() { return username+" ("+role+")"; }
    }
}
